    r.scale = s.ReadFloat();
    r.miniOffset.x = (float)s.ReadInt(); r.miniOffset.y = (float)s.ReadInt();
    r.worldOffset.x = (float)s.ReadInt(); r.worldOffset.y = (float)s.ReadInt();
    int n = s.ReadInt();
    for (int k = 0; k < n; ++k) {
