                while (!G->PathLoaded()) { G->NewScriptFrame(); if (IsActiveThreadTerminating()) return; }
                if (IsActiveThreadTerminating()) return;
                G->Trigger();
            }
        }
        if (IsActiveThreadTerminating()) return;
        L("CS_OPENGRAVE_PATHDOOR"); L("objective"); L("fade"); L("remove");
